package repository;

import domain.entities.User;
import domain.exceptions.EntityNotFoundException;
import domain.validators.Validator;

import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;


/**
 * Repository that stores the users in a PostgreSQL database.
 * The id of a new user is generated by the database.
 */
@SuppressWarnings({"SqlNoDataSourceInspection", "SqlResolve"})
public class UserDBRepository implements Repository<Long, User> {
    private final Validator<User> validator;
    private final String url;
    private final String user;
    private final String password;


    /**
     * Creates the repository with the validator and the connection parameters.
     *
     * @param validator the validator used to check the users before saving or updating
     * @param url       the url of the database
     * @param user      the database user
     * @param password  the database password
     */
    public UserDBRepository(Validator<User> validator, String url, String user, String password) {
        this.validator = validator;
        this.url = url;
        this.user = user;
        this.password = password;
    }

    private Connection connect() throws SQLException {
        return DriverManager.getConnection(url, user, password);
    }

    /**
     * Finds a user by its id.
     *
     * @param id the id of the user
     * @return the user with the given id
     * @throws IllegalArgumentException                  if id is null
     * @throws domain.exceptions.EntityNotFoundException if no user has this id
     * @throws domain.exceptions.RepositoryException     if the database cannot be accessed
     */
    @Override
    public User findOne(Long id) {
        if (id == null) {
            throw new IllegalArgumentException("id must not be null\n");
        }

        String sql = "SELECT first_name, last_name FROM users WHERE id=?";
        try (Connection connection = connect();
             PreparedStatement statement = connection.prepareStatement(sql)) {
            statement.setLong(1, id);
            try (ResultSet resultSet = statement.executeQuery()) {
                if (!resultSet.next()) {
                    throw new EntityNotFoundException("Entity with id " + id + " not found");
                }
                return new User(id, resultSet.getString("first_name"), resultSet.getString("last_name"));
            }
        } catch (SQLException e) {
            throw SQLErrors.toRepositoryException("read user " + id, e);
        }
    }

    /**
     * Returns all the users from the database.
     *
     * @return all the users
     * @throws domain.exceptions.RepositoryException if the database cannot be accessed
     */
    @Override
    public Iterable<User> findAll() {
        String sql = "SELECT id, first_name, last_name FROM users";
        List<User> users = new ArrayList<>();
        try (Connection connection = connect();
             PreparedStatement statement = connection.prepareStatement(sql);
             ResultSet resultSet = statement.executeQuery()) {
            while (resultSet.next()) {
                users.add(new User(resultSet.getLong("id"),
                        resultSet.getString("first_name"),
                        resultSet.getString("last_name")));
            }
            return users;
        } catch (SQLException e) {
            throw SQLErrors.toRepositoryException("read users", e);
        }
    }

    /**
     * Validates and saves a new user. The id is generated by the database
     * and is set on the given user.
     *
     * @param entity the user to save
     * @throws IllegalArgumentException                  if the user is null
     * @throws domain.exceptions.ValidationException     if the user is not valid
     * @throws domain.exceptions.RepositoryException     if the database cannot be accessed
     */
    @Override
    public void save(User entity) {
        if (entity == null) {
            throw new IllegalArgumentException("entity must not be null\n");
        }
        validator.validate(entity);

        String sql = "INSERT INTO users (first_name, last_name) VALUES (?, ?) RETURNING id";
        try (Connection connection = connect();
             PreparedStatement statement = connection.prepareStatement(sql)) {
            statement.setString(1, entity.getFirstName());
            statement.setString(2, entity.getLastName());
            try (ResultSet resultSet = statement.executeQuery()) {
                resultSet.next();
                entity.setId(resultSet.getLong("id"));
            }
        } catch (SQLException e) {
            throw SQLErrors.toRepositoryException("save user", e);
        }
    }

    /**
     * Validates the user and updates its first and last name.
     *
     * @param entity the user with the new data
     * @return an empty Optional if the user was updated, or the given user if its id does not exist
     * @throws IllegalArgumentException                  if the user is null
     * @throws domain.exceptions.ValidationException     if the user is not valid
     * @throws domain.exceptions.RepositoryException     if the database cannot be accessed
     */
    @Override
    public Optional<User> update(User entity) {
        if (entity == null) {
            throw new IllegalArgumentException("entity must not be null\n");
        }
        validator.validate(entity);
        if (entity.getId() == null) {
            return Optional.of(entity);
        }

        String sql = "UPDATE users SET first_name = ?, last_name = ? WHERE id = ?";
        try (Connection connection = connect();
             PreparedStatement statement = connection.prepareStatement(sql)) {
            statement.setString(1, entity.getFirstName());
            statement.setString(2, entity.getLastName());
            statement.setLong(3, entity.getId());

            int updatedRows = statement.executeUpdate();
            if (updatedRows == 0) {
                return Optional.of(entity);
            }
            return Optional.empty();
        } catch (SQLException e) {
            throw SQLErrors.toRepositoryException("update user " + entity.getId(), e);
        }
    }

    /**
     * Deletes the user with the given id.
     *
     * @param id the id of the user to delete
     * @return the deleted user, or an empty Optional if no user has this id
     * @throws IllegalArgumentException                  if id is null
     * @throws domain.exceptions.RepositoryException     if the database cannot be accessed
     *                                                   or the user is still referenced by friendships
     */
    @Override
    public Optional<User> delete(Long id) {
        if (id == null) {
            throw new IllegalArgumentException("id must not be null\n");
        }

        String sql = "DELETE FROM users WHERE id = ? RETURNING first_name, last_name";
        try (Connection connection = connect();
             PreparedStatement statement = connection.prepareStatement(sql)) {
            statement.setLong(1, id);
            try (ResultSet resultSet = statement.executeQuery()) {
                if (!resultSet.next()) {
                    return Optional.empty();
                }
                return Optional.of(new User(id,
                        resultSet.getString("first_name"),
                        resultSet.getString("last_name")));
            }
        } catch (SQLException e) {
            throw SQLErrors.toRepositoryException("delete user " + id, e);
        }
    }
}